import{_ as e,c as t,o as r,a as s}from"./app.19f3f8f0.js";const m=JSON.parse('{"title":"Card series guide","description":"","frontmatter":{},"headers":[{"level":2,"title":"Series list","slug":"series-list","link":"#series-list","children":[]},{"level":2,"title":"Example 90-day stream","slug":"example-90-day-stream","link":"#example-90-day-stream","children":[]},{"level":2,"title":"Production checklist","slug":"production-checklist","link":"#production-checklist","children":[]}],"relativePath":"replybridge/marketing/series-overview.md"}'),d={name:"replybridge/marketing/series-overview.md"},a=s('<h1 id="card-series-guide" tabindex="-1">Card series guide <a class="header-anchor" href="#card-series-guide" aria-hidden="true">#</a></h1><p><strong>On this website:</strong> We publish matching lessons you can link from DMs—see the <strong><a href="/replybridge/series/">Instagram mini-series</a></strong> (Episodes 1–6, expandable).</p><p>Themes and suggested order for Instagram <strong>vertical multi-slide</strong> series <strong>A–F</strong>. Full copy, PNG specs, and filenames follow reply-bridge <code>marketing/series/</code> and <code>CARD_NEWS_STRUCTURE.md</code>.</p><hr><h2 id="series-list" tabindex="-1">Series list <a class="header-anchor" href="#series-list" aria-hidden="true">#</a></h2><table><thead><tr><th>Series</th><th>One-line topic</th><th>Example <code>utm_campaign</code></th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Private Reply &amp; Auto DM basics</td><td><code>auto-dm-basics</code></td></tr><tr><td><strong>B</strong></td><td>Public <strong>Auto Reply</strong> — thread reply vs DM</td><td><code>auto-reply-101</code></td></tr><tr><td><strong>C</strong></td><td><strong>Automation window</strong>, notifications, reward extension</td><td><code>automation-window</code></td></tr><tr><td><strong>D</strong></td><td><strong>Keywords</strong> &amp; <strong>once per user</strong> tactics</td><td><code>keyword-rules</code></td></tr><tr><td><strong>E</strong></td><td>Launch / event playbook</td><td><code>event-launch-playbook</code></td></tr><tr><td><strong>F</strong></td><td><strong>Official API &amp; trust</strong> — account types, expectations</td><td><code>official-api-trust</code></td></tr></tbody></table><p>Each series is usually <strong>10 slides</strong>.</p><hr><h2 id="example-90-day-stream" tabindex="-1">Example 90-day stream <a class="header-anchor" href="#example-90-day-stream" aria-hidden="true">#</a></h2><table><thead><tr><th>Window</th><th>Order</th></tr></thead><tbody><tr><td>Weeks 1–2</td><td>A → B (feature basics)</td></tr><tr><td>Weeks 3–4</td><td>D → C (tactics → window)</td></tr><tr><td>Weeks 5–6</td><td>E (use cases)</td></tr><tr><td>Week 7</td><td>F (trust)—strong before promos</td></tr></tbody></table><hr><h2 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-hidden="true">#</a></h2><ul><li>Resolution &amp; crop: e.g. <strong>1080×1350</strong> per design rules.</li><li>Proofread and align with reply-bridge <code>copy.md</code>.</li><li>Match UTMs to series names for cleaner analytics.</li></ul><hr><p><a href="/replybridge/marketing/">Back to marketing hub</a></p>',15),o=[a];function i(n,c,l,h,g,p){return r(),t("div",null,o)}const y=e(d,[["render",i]]);export{m as __pageData,y as default};
